8	/**
9	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>} where YY is
10	 * the two-digit (zero-padded) last two digits of the {@code registrationDate} year (e.g.
11	 * {@code SMI-0007-M26}). Runs after {@link AssignOwnerCustomerCode} has stamped the customer code
12	 * and {@link BuildOwner} has set the registration date, and before {@link SaveOwner} persists the
13	 * entity, mutating the built owner in place so the saved and returned record carries the number.
14	 */
15	public class AssignOwnerMembershipNumber {
16	
17	    public void service(@Val Owner owner) {
18	        String yy = String.format(Locale.ROOT, "%02d", owner.getRegistrationDate().getYear() % 100);
19	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
20	    }
21	}
