7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners — before this create —
9	 * whose firstName and lastName both match the new owner's, compared case-insensitively. Runs after
10	 * {@link BuildOwner} has created the entity and before {@link SaveOwner} persists it, so the count
11	 * reflects only pre-existing owners (the new owner has no id yet and is skipped). The count is
12	 * stored on the built owner so the saved and returned record carries it.
13	 */
14	public class CountOwnerNamesakes {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = owner.getFirstName();
18	        String lastName = owner.getLastName();
19	        long count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
22	                continue;
23	            }
24	            if (firstName != null && lastName != null
25	                    && firstName.equalsIgnoreCase(existing.getFirstName())
26	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
27	                count++;
28	            }
29	        }
30	        owner.setNamesakeCount((int) count);
31	    }
32	}
